package com.example.starter.scene.dto;

/**
 * 单个碰撞对象批处理操作。type 取值：ADD、MODIFY、DELETE、RENAME。
 *
 * @param type 操作类型
 * @param objectId DELETE/RENAME 的目标对象 ID
 * @param newObjectId RENAME 的新对象 ID，必须全局未占用
 * @param object ADD/MODIFY 携带的对象主体
 */
public record ObjectOp(String type, String objectId, String newObjectId, CollisionObjectBody object) {

    /** 新增对象操作类型。 */
    public static final String ADD = "ADD";
    /** 修改对象操作类型。 */
    public static final String MODIFY = "MODIFY";
    /** 删除对象操作类型。 */
    public static final String DELETE = "DELETE";
    /** 重命名对象操作类型。 */
    public static final String RENAME = "RENAME";
}

package com.example.starter.scene.dto;

/**
 * 单个附着/解除附着操作。type 取值：ATTACH、DETACH。
 *
 * @param type 操作类型
 * @param objectId 目标对象 ID
 * @param linkName ATTACH 的目标机器人 Link，必须已存在
 * @param frameId DETACH 后对象回到世界时使用的坐标系，为空时默认 world
 */
public record AttachOp(String type, String objectId, String linkName, String frameId) {

    /** 附着操作类型。 */
    public static final String ATTACH = "ATTACH";
    /** 解除附着操作类型。 */
    public static final String DETACH = "DETACH";
}

package com.example.starter.scene.dto;

import java.util.List;

/**
 * 一次 Planning Scene 批量修改请求。携带幂等键与期望版本，全部操作原子生效。
 *
 * @param requestId 幂等请求 ID；同键同参返回原结果，同键异参返回 409
 * @param expectedVersion 期望的当前场景版本；不一致时返回 409 与差异列表
 * @param jointUpdates 关节位置更新列表，同一批内关节名唯一
 * @param objectOps 碰撞对象新增/修改/删除/重命名操作列表，同一批内对象 ID 唯一
 * @param attachOps 附着/解除附着操作列表
 */
public record ApplyRequest(String requestId,
                           Long expectedVersion,
                           List<JointUpdate> jointUpdates,
                           List<ObjectOp> objectOps,
                           List<AttachOp> attachOps) {
}

package com.example.starter.scene.dto;

/**
 * 批量修改成功响应。
 *
 * @param requestId 回显的幂等请求 ID
 * @param version 本次提交产生的场景新版本号
 * @param replayed 是否为幂等重放（同键同参直接返回首次结果）
 */
public record ApplyResponse(String requestId, long version, boolean replayed) {
}

